resource "aws_lambda_function" "worker" {
  function_name = var.name
  role          = var.role_arn

  tags = merge(var.common_tags, {
    Service   = "worker"
    ManagedBy = "terraform"
  })
}

variable "name" { type = string }
variable "role_arn" { type = string }
variable "common_tags" { type = map(string) }
